"""Render ``robots.txt`` from the validated ``robots`` config.

Output is sorted, ASCII and deterministic. robots.txt is advisory: it asks
well-behaved crawlers to stay away and stops nobody else.
"""

from __future__ import annotations

from importlib import resources

from reach_around.config.robots import TOKEN, Robots

_HEADER = (
    "# robots.txt is advisory. It asks well-behaved crawlers to follow these\n"
    "# rules; it is not access control and does not stop anyone who ignores it.\n"
    "# Generated by Reach Around.\n"
)


def parse_crawler_list(text: str) -> list[str]:
    """Return the tokens in ``text``: one per line, ``#`` lines are comments.

    Any line that is not a plain token is refused, so a damaged data file can
    never inject a directive into ``robots.txt``.
    """
    tokens: list[str] = []
    seen: set[str] = set()
    for number, line in enumerate(text.splitlines(), start=1):
        if not line or line.startswith("#"):
            continue
        if not TOKEN.fullmatch(line) or line == "*":
            raise ValueError(f"crawler list line {number} is not a token: {line!r}")
        if line.lower() in seen:
            raise ValueError(f"crawler list line {number} repeats {line!r}")
        seen.add(line.lower())
        tokens.append(line)
    if not tokens:
        raise ValueError("crawler list has no tokens")
    return tokens


def ai_crawler_tokens() -> list[str]:
    """Return the packaged AI crawler tokens, in file order."""
    path = resources.files("reach_around.site") / "data" / "ai_crawlers.txt"
    return parse_crawler_list(path.read_text(encoding="ascii"))


def render_robots(robots: Robots) -> str:
    """Return the ``robots.txt`` text for ``robots``."""
    blocked: dict[str, str] = {}
    sources = list(robots.block)
    if robots.ai_crawlers == "block":
        sources += ai_crawler_tokens()
    for token in sources:
        blocked.setdefault(token.lower(), token)
    lines = [
        _HEADER,
        "User-agent: *",
        "Allow: /" if robots.allow_all else "Disallow: /",
    ]
    for key in sorted(blocked):
        lines += ["", f"User-agent: {blocked[key]}", "Disallow: /"]
    text = "\n".join(lines) + "\n"
    text.encode("ascii")  # fails loudly rather than writing non-ASCII
    return text
